class Solution {
    public int[] numberOfPairs(int[] nums) {
        int[] count = new int[101];
        for (int value : nums) {
            count[value]++;
        }
        int pairs = 0;
        int leftovers = 0;
        for (int frequency : count) {
            pairs += frequency / 2;
            leftovers += frequency % 2;
        }
        return new int[]{pairs, leftovers};
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int[] numberOfPairs(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int value : nums) {
            counts.put(value, counts.getOrDefault(value, 0) + 1);
        }
        int pairs = 0;
        int leftovers = 0;
        for (int frequency : counts.values()) {
            pairs += frequency / 2;
            leftovers += frequency % 2;
        }
        return new int[]{pairs, leftovers};
    }
}

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int[] numberOfPairs(int[] nums) {
        Set<Integer> waiting = new HashSet<>();
        int pairs = 0;
        for (int value : nums) {
            if (waiting.contains(value)) {
                waiting.remove(value);
                pairs++;
            } else {
                waiting.add(value);
            }
        }
        return new int[]{pairs, waiting.size()};
    }
}

import java.util.Arrays;

class Solution {
    public int[] numberOfPairs(int[] nums) {
        Arrays.sort(nums);
        int pairs = 0;
        int leftovers = 0;
        int index = 0;
        while (index < nums.length) {
            if (index + 1 < nums.length && nums[index] == nums[index + 1]) {
                pairs++;
                index += 2;
            } else {
                leftovers++;
                index++;
            }
        }
        return new int[]{pairs, leftovers};
    }
}

class Solution {
    public int[] numberOfPairs(int[] nums) {
        boolean[] waiting = new boolean[101];
        int pairs = 0;
        for (int value : nums) {
            if (waiting[value]) {
                waiting[value] = false;
                pairs++;
            } else {
                waiting[value] = true;
            }
        }
        int leftovers = nums.length - pairs * 2;
        return new int[]{pairs, leftovers};
    }
}
